using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU1", 10.00m, 2);
        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_SumsCorrectly()
    {
        _cart.AddItem("A", 5.00m, 1);
        _cart.AddItem("B", 3.50m, 4);
        Assert.AreEqual(19.00m, _cart.GetTotal());
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("X", 9.99m, 1);
        Assert.IsTrue(_cart.RemoveItem("X"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_ExcludedFromTotal()
    {
        _cart.AddItem("X", 10.00m, 1);
        _cart.AddItem("Y", 5.00m, 2);
        _cart.RemoveItem("X");
        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistingSku_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("MISSING"));
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- ApplyPromoCode ---

    [TestMethod]
    public void ApplyPromoCode_ValidSave10_ReturnsTrue()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("SAVE10"));
    }

    [TestMethod]
    public void ApplyPromoCode_Save10_Applies10PercentDiscount()
    {
        _cart.AddItem("A", 100.00m, 1);
        _cart.ApplyPromoCode("SAVE10");
        Assert.AreEqual(90.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_Half_Applies50PercentDiscount()
    {
        _cart.AddItem("A", 80.00m, 2);
        _cart.ApplyPromoCode("HALF");
        Assert.AreEqual(80.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("BOGUS"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_NoDiscount()
    {
        _cart.AddItem("A", 50.00m, 1);
        _cart.ApplyPromoCode("BOGUS");
        Assert.AreEqual(50.00m, _cart.GetTotal());
    }
}

